operation.search:
if (DBPessoal::utilizaFiltroLotacoesPorUsuario()) {
  $oLotacoesUsuario = DBPessoal::buscaLotacoesPorUsuario();
  $aWhere[] = " case 
                  when rhpessoalmov.rh02_seqpes is not null 
                    then rhpessoalmov.rh02_lota in (".implode(",",$oLotacoesUsuario->aLotacoes).") 
                  else true 
                end ";
}
